package dev.example.store;

import jakarta.persistence.Entity;
import jakarta.persistence.Id;

@Entity
public class Customer {

    @Id
    private Long id;
    private String name;
    private String email;
    private String tier;

    protected Customer() {
    }

    public Customer(Long id, String name, String email, String tier) {
        this.id = id;
